<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';require_role(['customer']);verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$subject=trim($_POST['subject']??'');$desc=trim($_POST['description']??'');if($subject===''||$desc===''){flash('error','Enter a subject and description.');redirect('my_complaints.php');}$pdo->prepare("INSERT INTO complaints(customer_id,subject,description) VALUES(?,?,?)")->execute([current_user()['customer_id'],$subject,$desc]);audit($pdo,'SUBMIT COMPLAINT',$subject);flash('success','Your complaint has been submitted.');redirect('my_complaints.php');}
$s=$pdo->prepare("SELECT * FROM complaints WHERE customer_id=? ORDER BY created_at DESC");$s->execute([current_user()['customer_id']]);$rows=$s->fetchAll();$pageTitle='My complaints';require 'includes/header.php';?>
<div class="two-col"><div class="panel"><h3>Submit a complaint</h3><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Subject *</label><input name="subject" required><label>Describe the issue *</label><textarea name="description" rows="5" required></textarea><button class="btn primary">Submit complaint</button></form></div><div class="panel"><h3>Complaint guidance</h3><p class="muted">Use this form to report billing concerns, meter-reading problems, service interruptions or other account issues. Staff can review and update the status.</p></div></div>
<div class="panel"><h3>My submitted complaints</h3><table><thead><tr><th>Subject</th><th>Description</th><th>Status</th><th>Submitted</th><th>Response</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['subject'])?></td><td><?=e($r['description'])?></td><td><?=e(str_replace('_',' ',ucfirst($r['status'])))?></td><td><?=e($r['created_at'])?></td><td><?=e($r['resolution_notes']??'Awaiting response')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No complaints submitted.</td></tr><?php endif;?></tbody></table></div><?php require 'includes/footer.php';?>
